def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append((color, cells))

    # Find the long thin line-like marker, and recolor the nearest other object.
    def line_score(cells):
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        bh, bw = max(rs) - min(rs) + 1, max(cs) - min(cs) + 1
        return max(bh, bw) / min(bh, bw)

    marker = max(comps, key=lambda obj: (line_score(obj[1]), len(obj[1])))
    mc, cells = marker
    target = min(
        (obj for obj in comps if obj is not marker),
        key=lambda obj: min(abs(y-a) + abs(x-b)
                            for y, x in cells for a, b in obj[1])
    )

    out = [row[:] for row in grid]
    for r, c in target[1]:
        out[r][c] = mc
    return out
